#[tauri::command]
fn open_file(app: tauri::AppHandle, name: String) -> Result<String, String> {
    // Allowlist characters only, which inherently excludes separators and parent refs
    if !name.chars().all(|c| c.is_ascii_alphanumeric() || c == . || c == - || c == _) {
        return Err("illegal name".into());
    }
    let dir = app.path().app_data_dir().map_err(|e| e.to_string())?;
    let full = dir.join(&name);
    // After normalization, confirm it is still inside the data dir to block symlink escapes
    let canon = full.canonicalize().map_err(|e| e.to_string())?;
    if !canon.starts_with(&dir) { return Err("out of scope".into()); }
    std::fs::read_to_string(canon).map_err(|e| e.to_string())
}

use keyring::Entry;

fn get_or_create_key() -> keyring::Result<Entry> {
    let e = Entry::new("SentryDesk", "db-key")?;
    if e.get_password().is_err() {
        // Generate a random key on first run and hand it to the OS keystore
        let mut buf = [0u8; 32];
        getrandom::getrandom(&mut buf).unwrap();
        use base64::Engine;
        let b64 = base64::engine::general_purpose::STANDARD.encode(buf);
        e.set_password(&b64)?;
    }
    Ok(e)
}

