fn is_safe_ip(ip: std::net::IpAddr) -> bool {
    match ip {
        std::net::IpAddr::V4(v4) => {
            !(v4.is_loopback()
              || v4.is_private()
              || v4.is_link_local()      // 169.254.0.0/16, home of the metadata address
              || v4.is_broadcast()
              || v4.is_unspecified())
        }
        std::net::IpAddr::V6(v6) => {
            !(v6.is_loopback() || v6.is_unspecified())
            // Also handle ::ffff: mapping and ULA fc00::/7 separately
        }
    }
}

// Keep both keys, try both on verify, sign only with the newest
fn verify_any(sig: &[u8], data: &[u8]) -> bool {
    [&KEY_V2, &KEY_V1].iter().any(|k| verify(sig, data, k))
}
fn sign(data: &[u8]) -> Vec<u8> {
    sign_with(data, &KEY_V2)   // new signatures always use the newest version
}

